def _route_selected(*, scope, path, mount=False):
    rt = scope.get('fastapi.telemetry')
    if not isinstance(rt, _RequestTelemetry):
        return
    if mount:
        path = path.removesuffix('/{path}')
        rt._mount_prefix += path
        rt.route = rt._mount_prefix + '/{path}'
    else:
        rt.route = rt._mount_prefix + path
    if rt.span is not None:
        rt.span.set_attribute('http.route', rt.route)
        rt.span.update_name(
            f'{rt.span_method} {rt.route}'
        )

